const d = $json; const c = d.classification, f = d.final;
const tid = d.ticket ? d.ticket.ticket_id : '';
return { json: {
  email_id: d.email_id, received_at: d.received_at, from_email: d.from_email,
  intent: c.intent, secondary_intent: c.secondary_intent || '', order_id: c.order_id || '',
  language: c.language, sentiment: c.sentiment, confidence: c.confidence,
  order_found: d.order_found ? 'TRUE' : 'FALSE',
  action_taken: f.action_taken + (d.ticket ? (d.ticket.mode === 'update' ? ' + ticket_updated' : ' + ticket_created') : ''),
  needs_human: f.needs_human ? 'TRUE' : 'FALSE', ticket_id: tid,
  reply_draft: f.reply_draft, prompt_version: d.prompt_version, processed_at: new Date().toISOString(),
  error: f.error || '', notes: f.notes
}};

const fin = $('Finalize Result1').item.json;
const f = fin.final, c = fin.classification;
const existing = $json && $json.ticket_id ? $json : null;     // row returned by "Get Open Ticket" (empty item if none)
const now = new Date().toISOString();
const noteLine = `[${now}] ${fin.email_id}: ${c.summary}${fin.injection_flag ? ' (prompt-injection attempt ignored)' : ''}`;
if (existing && String(existing.status).toLowerCase() !== 'closed') {
  const ids = String(existing.email_ids || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!ids.includes(fin.email_id)) ids.push(fin.email_id);
  return { json: { ...fin, ticket: { mode: 'update', ticket_id: existing.ticket_id, email_ids: ids.join(', '),
     notes: ((existing.notes ? existing.notes + '\n' : '') + noteLine).slice(0, 4000), updated_at: now,
     priority: (existing.priority === 'High' || f.ticket_priority === 'High') ? 'High' : existing.priority || f.ticket_priority } } };
}
return { json: { ...fin, ticket: { mode: 'create', ticket_id: 'TKT-' + fin.email_id, created_at: now, updated_at: now,
   order_id: c.order_id || '', customer_email: fin.from_email, email_ids: fin.email_id, intent: c.intent,
   priority: f.ticket_priority, status: 'Open', summary: c.summary, notes: noteLine } } };

const base = $json;                       // context produced by the previous steps (agent merged in by "Collect Agent Output")
const c = base.classification;
const oc = base.order_context;
const reasons = [...(base.needs_human_reasons || [])];
const notes = [];
let draft = String(base.reply_draft_raw || '').trim();
let error = base.classification_error || base.agent_error || null;
let action = '';
const first = (base.from_name || '').split(' ')[0] || 'there';

if (base.other_handler) {
  action = base.other_handler.action; draft = base.other_handler.draft || '';
  notes.push(base.other_handler.note);
  if (base.other_handler.human) reasons.push('other_requires_human');
} else {
  action = 'drafted_reply';
  if (!draft) { reasons.push('agent_no_draft'); action = 'escalated_to_human'; }
}

// ---- guardrails on the draft ----
if (draft) {
  draft = draft.replace(/\n?\s*(warm regards|regards|best regards|thanks|thank you)[,!.]?\s*\n+\s*(team kesar|kesar team|kesar & co\.?)\s*$/i, '').trim();
  if (!/Team Kesar\s*$/i.test(draft)) draft += '\n\nWarm regards,\nTeam Kesar';
  if (/\p{Extended_Pictographic}/u.test(draft)) { reasons.push('guardrail_emoji'); draft = draft.replace(/\p{Extended_Pictographic}/gu, ''); }
  const urls = draft.match(/https?:\/\/[^\s)>\]]+/g) || [];
  const allowed = oc && oc.order && oc.order.tracking_url ? [oc.order.tracking_url] : [];
  if (urls.some(u => !allowed.includes(u.replace(/[.,]$/, '')))) reasons.push('guardrail_unknown_url');
  if (oc && oc.lookup_status === 'PRIVACY_BLOCKED' && /(KC-\d{4}.{0,40}(shipped|delivered|out for delivery|processing))|track\.example|address/i.test(draft)) reasons.push('guardrail_privacy_leak');
  if (/\b(cures?|cured|heals?|healed|treats? (your )?(eczema|acne|psoriasis))\b/i.test(draft) && !/(not|cannot|can't|don't|do not|isn't|aren't|never)[^.]{0,60}\b(cure|treat|heal)/i.test(draft)) reasons.push('guardrail_medical_claim');
  if (/(approved|will be credited within 24 hours)/i.test(draft) && base.injection_flag) reasons.push('guardrail_injection_echo');
}

// ---- needs-human policy ----
const el = oc && oc.eligibility ? oc.eligibility : {};
const dec = el.decision || '';
if (oc) {
  if (['NOT_FOUND','PRIVACY_BLOCKED','MULTIPLE_ORDERS'].includes(oc.lookup_status)) reasons.push('order_' + oc.lookup_status.toLowerCase());
  if (/^(NOT_ELIGIBLE|OUTSIDE_48H|PHOTOS_RECEIVED_PENDING_VERIFICATION)/.test(dec)) reasons.push('refund_decision_needs_review');
}
if (base.agent_escalate) { reasons.push('agent_requested_escalation'); if (base.agent_escalate_reason) notes.push('Agent: ' + base.agent_escalate_reason); }
const needs_human = reasons.length > 0;

// ---- ticket rules ----
const ticketIntents = ['return_refund', 'complaint'];
const needsTicket = !base.other_handler && (ticketIntents.includes(c.intent) || ticketIntents.includes(c.secondary_intent));
const serious = ['damaged_leaking','wrong_item','missing_item'].includes(c.issue_type);
const priority = (c.intent === 'complaint' || c.secondary_intent === 'complaint' || c.sentiment === 'angry' || serious) ? 'High' : 'Medium';
if (base.injection_flag) notes.push('SECURITY: possible prompt-injection text in email; ignored.');
if (el.decision) notes.push('Eligibility: ' + el.decision.split(':')[0]);
if (reasons.length) notes.push('needs_human reasons: ' + reasons.join(', '));

return { json: { ...base, final: {
  action_taken: action, needs_human, needs_human_reasons: reasons, reply_draft: draft, error, notes: notes.join(' | '),
  needs_ticket: needsTicket, ticket_priority: priority
} } };

const ctx = $('Context Hub1').item.json;
let out = $json.output ?? $json.text ?? '';
let reply = '', escalate = false, reason = '', err = null;
if ($json.error) err = 'Agent error: ' + (typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error)));
if (out && typeof out === 'object') { reply = out.reply || ''; escalate = !!out.escalate; reason = out.escalate_reason || ''; }
else if (typeof out === 'string' && out.trim()) {
  let s = out.replace(/```json|```/gi, '').trim();
  const m = s.match(/###\s*ESCALATE\s*:\s*(yes|no|true|false)/i);
  const r = s.match(/###\s*REASON\s*:\s*(.*)/i);
  if (m) {
    escalate = /yes|true/i.test(m[1]);
    reason = r ? r[1].trim().replace(/^none$/i, '') : '';
    reply = s.split(/###\s*ESCALATE/i)[0].trim();
  } else {
    // fallback: model returned JSON anyway, or plain text only
    const a = s.indexOf('{'), b = s.lastIndexOf('}');
    try { const p = JSON.parse(a >= 0 && b > a ? s.slice(a, b + 1) : s); reply = p.reply || ''; escalate = !!p.escalate; reason = p.escalate_reason || ''; }
    catch (e) { reply = s; }
  }
}
return { json: { ...ctx, reply_draft_raw: reply, agent_escalate: escalate, agent_escalate_reason: reason, agent_error: err } };

// get_order tool: returns ONLY the order already verified for this sender (privacy enforced upstream in code).
let ctx = null;
try { ctx = $json; } catch (e) {}
if (!ctx || !ctx.order_context) { try { ctx = $('Order Lookup & Rules').item.json; } catch (e) {} }
if (!ctx || !ctx.order_context) { try { ctx = $('Prepare Product Context').item.json; } catch (e) {} }
if (!ctx || !ctx.order_context) return JSON.stringify({ error: 'no order context available' });
const oc = ctx.order_context;
if (oc.lookup_status === 'VERIFIED') return JSON.stringify({ status: 'VERIFIED', order: oc.order, return_or_damage_rules_result: oc.eligibility });
if (oc.lookup_status === 'PRIVACY_BLOCKED') return JSON.stringify({ status: 'PRIVACY_BLOCKED', message: oc.privacy_note });
if (oc.lookup_status === 'MULTIPLE_ORDERS') return JSON.stringify({ status: 'MULTIPLE_ORDERS', message: 'Several orders found for this sender; ask the customer which order ID they mean. Do not guess.' });
if (oc.lookup_status === 'NOT_REQUIRED') return JSON.stringify({ status: 'NOT_REQUIRED', message: 'No order lookup was needed for this email.' });
return JSON.stringify({ status: 'NOT_FOUND', message: 'No matching order. Do not invent details; ask the customer to confirm the order number used at checkout.' });

// Deterministic order lookup + privacy check + return/damage eligibility. Dates come from received_at, NOT the system clock.
const ctx = $('Validate Classification1').item.json;
let orders = $json.orders;
if (!orders && typeof $json.data === 'string') { try { orders = JSON.parse($json.data).orders; } catch (e) {} }
orders = orders || [];
const c = ctx.classification;
const sender = ctx.from_email;
const ymd = s => String(s).slice(0, 10);
const dayDiff = (a, b) => Math.round((Date.parse(ymd(a)) - Date.parse(ymd(b))) / 86400000);
const receivedDate = ymd(ctx.received_at);

let status = 'NOT_FOUND', order = null, matched_by = null, candidates = [];
if (c.order_id) {
  matched_by = 'order_id';
  const o = orders.find(x => x.order_id === c.order_id);
  if (o) {
    if (String(o.customer_email).toLowerCase() === sender) { status = 'VERIFIED'; order = o; }
    else status = 'PRIVACY_BLOCKED';        // order exists but belongs to someone else -> never expose details
  }
} else {
  matched_by = 'sender_email';
  candidates = orders.filter(x => String(x.customer_email).toLowerCase() === sender);
  if (candidates.length === 1) { status = 'VERIFIED'; order = candidates[0]; }
  else if (candidates.length > 1) status = 'MULTIPLE_ORDERS';
}

// ---- eligibility (only for return/refund/complaint flows with a verified order) ----
let eligibility = { applicable: false };
const wantsReturnFlow = ['return_refund','complaint'].includes(c.intent) || ['return_refund','complaint'].includes(c.secondary_intent);
const hasPhotos = (ctx.attachments || []).length > 0;
if (order && wantsReturnFlow) {
  const daysSince = order.delivered_date ? dayDiff(receivedDate, order.delivered_date) : null;
  const issue = c.issue_type;
  const e = { applicable: true, issue_type: issue, order_status: order.status, days_since_delivery: daysSince,
              photos_attached: hasPhotos, payment_method: order.payment_method, decision: '', facts: [] };
  const itemsTxt = order.items.map(i => `${i.qty} x ${i.name} @ INR ${i.unit_price}`).join('; ');
  e.facts.push('Order items: ' + itemsTxt, 'Items subtotal INR ' + order.subtotal + '; shipping INR ' + order.shipping_fee + '; COD fee INR ' + order.cod_fee + '; total INR ' + order.total);
  if (order.status !== 'delivered') {
    e.decision = order.status === 'cancelled'
      ? 'NOT_APPLICABLE: order was cancelled before dispatch; see cancellation/refund info on the order.'
      : 'NOT_YET_DELIVERED: a return/refund claim cannot be processed until the order is delivered; share tracking status instead.';
  } else if (['damaged_leaking','wrong_item','missing_item'].includes(issue)) {
    const within48h = daysSince !== null && daysSince <= 2;
    e.within_48h = within48h;
    if (!within48h) e.decision = 'OUTSIDE_48H: reported more than 48 hours after delivery; needs human review.';
    else if (!hasPhotos) e.decision = 'ELIGIBLE_PENDING_PHOTOS: within 48h. Ask for photos of the product and the outer box. After verification offer free replacement or full refund (customer choice). The 7-day/unopened rule does NOT apply.';
    else e.decision = 'PHOTOS_RECEIVED_PENDING_VERIFICATION: within 48h and photos attached. Tell customer the team will verify and then arrange replacement or full refund as they prefer. Do not promise before verification.';
    if (issue === 'wrong_item') e.facts.push('Wrong item: we pick up the wrong item and send the correct one at no cost.');
    if (issue === 'missing_item') e.facts.push('Missing item: verified against packing weight record, then we ship the missing item or refund its value.');
    e.facts.push('For damaged/wrong/missing cases the full amount paid (including fees) is refunded.');
  } else {
    const within7 = daysSince !== null && daysSince <= 7;
    e.within_7_days = within7;
    const claimsUnopened = /(unopened|sealed|seal intact|never opened|not opened|completely unopened)/i.test(ctx.body) && !/(used|didn'?t suit|did not suit|no difference)/i.test(ctx.body);
    const usedClaim = ['not_effective'].includes(issue) || /(used (them|it)|using the|been using|didn'?t suit|did not suit|no difference)/i.test(ctx.body);
    if (!within7) e.decision = 'NOT_ELIGIBLE_WINDOW: delivered ' + daysSince + ' days ago; returns accepted only within 7 days of delivery.';
    else if (usedClaim && !claimsUnopened) e.decision = 'NOT_ELIGIBLE_USED: customer says the product was used; only unused, unopened, sealed items can be returned (including "did not suit me" / "no results").';
    else e.decision = 'ELIGIBLE_RETURN: within 7 days of delivery and customer says items are unopened. Tell them to reply confirming; free reverse pickup in 2-3 business days; refund after quality check.';
    if (order.payment_method === 'cod') e.facts.push('COD order: refund via UPI or bank transfer; ask for UPI ID or bank details ONLY AFTER pickup is completed (do not ask for them now). COD fee INR 49 is non-refundable.');
    else e.facts.push('Prepaid: refund to original payment method within 5-7 business days after the returned item passes quality check.');
    e.facts.push('Shipping fee and COD fee are non-refundable for ordinary returns. Refundable item value = price of returned items only.');
    if (order.items.some(i => /Bridal Glow Kit/i.test(i.name))) e.facts.push('Combo/kit must be returned as a complete set.');
    e.delivered_date = order.delivered_date;
  }
  eligibility = e;
}

const order_context = { lookup_status: status, matched_by, candidates: candidates.map(x => x.order_id), order: status === 'VERIFIED' ? order : null,
  eligibility, privacy_note: status === 'PRIVACY_BLOCKED' ? 'An order with this ID exists but the sender email does not match the account holder. Do NOT reveal ANY order detail (not even whether it is shipped).' : null };

return { json: { ...ctx, order_context, order_found: status === 'VERIFIED', lookup_status: status, today: '2026-11-20' } };

const ctx = $('Validate Classification1').item.json;
const c = ctx.classification;
const first = (ctx.from_name || '').split(' ')[0] || 'there';
let draft = '', action = 'logged_no_reply_needed', note = '', human = false;
switch (c.other_type) {
  case 'spam': action = 'ignored_spam'; note = 'Unsolicited promotional/spam email. No reply.'; break;
  case 'thanks': action = 'logged_positive_feedback'; note = 'Positive feedback. No reply needed (optional thank-you).'; break;
  case 'partnership':
    action = 'drafted_redirect_partnerships'; human = true;
    note = 'Business/partnership enquiry - forward to partnerships team.';
    draft = `Hi ${first},\n\nThank you for your kind words about Kesar & Co. For collaborations and partnership enquiries, please write to partnerships@kesarandco.example and our team will take it forward from there.\n\nWarm regards,\nTeam Kesar`;
    break;
  case 'invoice_request':
    action = 'escalated_to_human'; human = true;
    note = 'GST invoice request: not covered by FAQ, so no answer drafted. Route to finance/accounts.'; break;
  default:
    action = 'escalated_to_human'; human = true;
    note = 'Intent "other" and not clearly spam/thanks/partnership - human to review.';
}
return { json: { ...ctx, order_context: null, order_found: false, lookup_status: 'NOT_REQUIRED',
  agent_output: draft, other_handler: { action, note, human, draft } } };

// Validate / repair the LLM classification, then apply HARD rules in code (not in the prompt).
const email = $('Loop Over Items1').item.json;
const THRESHOLD = 0.75;                       // below this -> human
const INTENTS = ['order_status','product_query','return_refund','complaint','other'];
const SENT = ['positive','neutral','negative','angry'];
const LANGS = ['en','hi','hinglish'];
const ISSUES = ['damaged_leaking','wrong_item','missing_item','change_of_mind','not_effective','delay','other'];
const OTHER = ['spam','thanks','partnership','invoice_request','unclear','other'];

let raw = $json.text ?? $json.output ?? '';
let parsed = null, error = null;
if ($json.error) error = 'LLM node error: ' + (typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error)));
if (typeof raw === 'object' && raw !== null) parsed = raw;
else if (typeof raw === 'string' && raw.trim()) {
  let s = raw.replace(/```json|```/gi, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) s = s.slice(a, b + 1);
  try { parsed = JSON.parse(s); } catch (e) { error = 'Invalid JSON from LLM: ' + e.message; }
}

const text = (email.subject + '\n' + email.body);
const idMatches = [...new Set((text.match(/KC-\d{4}/gi) || []).map(x => x.toUpperCase()))];

let c = null, fallback = false;
if (parsed && typeof parsed === 'object') {
  c = {
    intent: parsed.intent, secondary_intent: parsed.secondary_intent ?? null,
    order_id: parsed.order_id ?? null, sentiment: parsed.sentiment, language: parsed.language,
    confidence: Number(parsed.confidence), summary: String(parsed.summary || '').slice(0, 200),
    issue_type: parsed.issue_type ?? null, other_type: parsed.other_type ?? null,
    mentions_skin_reaction: !!parsed.mentions_skin_reaction,
    medical_claim_request: !!parsed.medical_claim_request,
    is_spam: !!parsed.is_spam
  };
  const okEnum = (v, list) => list.includes(v);
  if (!okEnum(c.intent, INTENTS) || !okEnum(c.sentiment, SENT) || !okEnum(c.language, LANGS) ||
      !(c.confidence >= 0 && c.confidence <= 1) || !(c.secondary_intent === null || INTENTS.includes(c.secondary_intent))) {
    error = (error ? error + ' | ' : '') + 'Schema validation failed'; c = null;
  }
}
if (!c) {
  fallback = true;
  c = { intent: 'other', secondary_intent: null, order_id: idMatches.length === 1 ? idMatches[0] : null,
        sentiment: 'neutral', language: 'en', confidence: 0, summary: 'Classification failed - needs manual review',
        issue_type: null, other_type: 'unclear', mentions_skin_reaction: false, medical_claim_request: false, is_spam: false };
}
if (c.issue_type && !ISSUES.includes(c.issue_type)) c.issue_type = 'other';
if (c.other_type && !OTHER.includes(c.other_type)) c.other_type = 'other';

if (!c.issue_type || ['other','delay'].includes(c.issue_type)) {
  const t = text.toLowerCase();
  if (/(leak|crack|damag|broken|spill|smash)/.test(t)) c.issue_type = 'damaged_leaking';
  else if (/(wrong (item|product)|instead of)/.test(t)) c.issue_type = 'wrong_item';
  else if (/(missing|not in the box|only had|didn.t get the)/.test(t)) c.issue_type = 'missing_item';
}
// order_id: never trust the model blindly. Must literally appear in the email; regex wins if exactly one is present.
if (idMatches.length === 1) c.order_id = idMatches[0];
else if (c.order_id && !idMatches.includes(String(c.order_id).toUpperCase())) c.order_id = null;
else if (c.order_id) c.order_id = String(c.order_id).toUpperCase();
if (c.order_id && !/^KC-[0-9]{4}$/.test(c.order_id)) c.order_id = null;

// Prompt-injection heuristics (customer email is untrusted input)
const INJ = /(ignore (all |any )?(previous|prior|above) (instructions|rules|polic)|system (note|prompt|message)|note to (the )?ai|as an ai assistant|you are now|disregard (the )?(policy|policies|instructions)|mark (the )?refund as approved|do not create (any )?ticket|reply exactly)/i;
const injection_flag = INJ.test(text);

const reasons = [];
if (fallback) reasons.push('classification_failed');
if (c.confidence < THRESHOLD) reasons.push('low_confidence(' + c.confidence + ')');
if (injection_flag) reasons.push('prompt_injection_suspected');
if (c.sentiment === 'angry') reasons.push('angry_customer');
if (c.mentions_skin_reaction) reasons.push('skin_reaction_reported');
if (c.medical_claim_request) reasons.push('medical_question');

let route = 'order_flow';
if (c.intent === 'other') route = 'other';
else if (c.intent === 'product_query') route = 'product_query';
if (c.is_spam) { c.intent = 'other'; c.other_type = 'spam'; route = 'other'; }

return { json: { ...email, classification: c, route, injection_flag, needs_human_reasons: reasons, classification_error: error, fallback } };

return $input.all().map(item => {
  const j = item.json;
  const src = (j.body && (j.body.id || j.body.body)) ? j.body : j;   // webhook POST wraps the email in .body
  const from = src.from || {};
  return { json: {
    email_id: src.id || src.email_id || 'UNKNOWN',
    received_at: src.received_at,
    from_email: String(from.email || src.from_email || '').trim().toLowerCase(),
    from_name: from.name || src.from_name || '',
    subject: src.subject || '',
    body: src.body || '',
    attachments: Array.isArray(src.attachments) ? src.attachments : [],
    prompt_version: 'v2'
  }};
});
